  mutating func readCustomValue(ofType type: UInt8) -> Any? {
    switch type {
    case 129:
      guard let raw = readValue() as? Int64 else { return nil }
      return NativeInteropAnEnum(rawValue: Int(raw))
    case 130:
      guard let raw = readValue() as? Int64 else { return nil }
      return NativeInteropAnotherEnum(rawValue: Int(raw))
    case 131:
